from ute_ue.data_transfers.lte_data_transfer import LteDataTransfer
from ute_ue.exceptions import DataTransferMissingArguments


class AndroidDataTransferHttp(LteDataTransfer):
    """Object responsible for managing Android data transfer."""
    # pylint: disable = protected-access, duplicate-code

    def __init__(self, name, dt_definition, configuration, android_ue, logger_name='ute_ue'):
        """

        :param name: name assigned to DataTransfer object
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: tool dependant configuration provided by UE instance needed for data transfer operations
        :param android_ue:
        """
        super(AndroidDataTransferHttp, self).__init__(name, dt_definition, configuration, logger_name)
        self.android_ue = android_ue
        self.success_started = False
        self.logger.debug('"{}" instance of AndroidDataTransferHttp created: '.format(self.name))
        self.is_running_ = False

    def start(self):
        """
        Starts data transfer with 'url' parameter if defined in dt_definition passed during initialization.

        :return: None
        :raises: :py:class:`ute_ue.exceptions.DataTransferIllegalArguments`: If 'url' parameter has not been provided
        """
        self.is_running_ = True
        if 'url' not in self._dt_definition.protocol_details:
            raise DataTransferMissingArguments("Please provide 'url' parameter if you use http protocol.")
        url = self._dt_definition.protocol_details['url']
        self.logger.info('Triggering HTTP request on the UE using url {}.'.format(url))
        http_out = self.android_ue._method_proxy('make_http', url)
        self.success_started = True
        self.logger.info('HTTP request triggered. Output: {}'.format(http_out))
        self.is_running_ = False

    def cleanup_data_transfer(self):
        """FTP data transfer cleanup"""
        self.release_data_transfer()

    def release_data_transfer(self):
        """HTTP data transfer cleanup"""
        if self.is_running():
            self.android_ue._method_proxy('kill_proc_on_ue_by_busybox', 'wget')
        self.logger.debug('Data transfer {} has finished. No need to release again'.format(self.name))

    def is_running(self):
        """
        Check if data transfer is running
        :return: boolean
        """
        return self.is_running_

    def stop(self):
        """
        Inherited.
        :return:
        """
        raise NotImplementedError()

    def await_finish(self):
        """
        Inherited.
        :return:
        """
        raise NotImplementedError()

    def check_data_transfer(self):
        """
        Inherited.
        :return:
        """
        raise NotImplementedError()

    def reset_statistics(self):
        """
        Inherited.
        :return:
        """
        raise NotImplementedError()

    def get_average_throughput(self):
        """
        Inherited.
        :return:
        """
        raise NotImplementedError()

    def get_datagram_loss(self):
        """
        Inherited.
        :return:
        """
        raise NotImplementedError()
